            // outward section; physical cuts remain independently eligible.
            let owner_allowed = if outward_possible && !owner_known {
                if let Some(owner) = node.owner {
                    log_cost(owners.len(), b)?;
                    owners.contains_key(&owner)
                } else {
                    true
                }
