                    let outward = if outward_possible {
                        let owner_allowed = if node.owner.is_some() {
                            true
                        } else {
                            log_cost(owners.len(), b)?;
                            owners.contains_key(&originals[ordinal].id().component)
                        };
                        owner_allowed
                            && b.with_retained(96, |b| distances.outward(ordinal, b))?

